globals:
# HuskyLens 1 por el adaptador OFDL: ev3dev lo ve como ev3-uart-84.
# Modo Data-EV3HSK, ocho enteros s32 medidos en el robot (no el orden del README):
# X, Y, W, H, ID, estado, 0, 0. Estado 1 = objeto, 7 = sin detección,
# 8 = sin aprendizaje, 9 = sin cámara, 0 = sin puerto o datos perdidos.
HUSKY_EV3_SYSFS = "/sys/class/"
HUSKY_EV3_MODO = "Data-EV3HSK"
husky_ev3_camaras = {}


def husky_ev3_leer_texto(ruta):
    with open(ruta) as archivo:
        return archivo.read().strip()


def husky_ev3_s32(datos, indice):
    valor = datos[4 * indice] | datos[4 * indice + 1] << 8 | datos[4 * indice + 2] << 16 | datos[4 * indice + 3] << 24
    return valor - 4294967296 if valor >= 2147483648 else valor


class HuskyEv3:
    def __init__(self, sensor):
        self.ruta = HUSKY_EV3_SYSFS + "lego-sensor/sensor%d/" % sensor.sensor_index
        if HUSKY_EV3_MODO not in husky_ev3_leer_texto(self.ruta + "modes").split():
            raise ValueError("no es el adaptador OFDL")
        if husky_ev3_leer_texto(self.ruta + "mode") != HUSKY_EV3_MODO:
            with open(self.ruta + "mode", "w") as archivo:
                archivo.write(HUSKY_EV3_MODO)
        self.bytes = 4 * int(husky_ev3_leer_texto(self.ruta + "num_values"))
        if self.bytes < 24:
            raise ValueError("faltan valores")
        self.estado = self.id = self.x = self.y = self.ancho = self.alto = 0

    def actualizar(self):
        # bin_data es una sola lectura de los ocho valores: no mezcla fotogramas.
        try:
            with open(self.ruta + "bin_data", "rb") as archivo:
                datos = archivo.read(self.bytes)
            valores = [husky_ev3_s32(datos, i) for i in range(6)]
        except (OSError, IndexError):
            valores = [0] * 6
        self.estado = valores[5]
        if self.estado == 1:
            self.x, self.y, self.ancho, self.alto, self.id = valores[:5]
        else:
            self.id = self.x = self.y = self.ancho = self.alto = 0


def husky_ev3(puerto, bloque):
    if puerto not in husky_ev3_camaras:
        sensor = rb_device(puerto, Ev3devSensor, bloque)
        try:
            husky_ev3_camaras[puerto] = HuskyEv3(sensor)
        except (OSError, ValueError):
            rb_fail(bloque, "No hay un adaptador HuskyLens OFDL en el puerto")
    return husky_ev3_camaras[puerto]


def husky_ev3_ve_id(puerto, numero, bloque):
    camara = husky_ev3(puerto, bloque)
    return camara.estado == 1 and camara.id == numero


def husky_ev3_posicion(puerto, eje, centro, bloque):
    # Origen en el centro: 320 x 240 píxeles, X de -160 a 160 y Y de -120 a 120.
    camara = husky_ev3(puerto, bloque)
    if camara.estado != 1:
        return 0
    if eje == "x":
        return camara.x - 160 if centro else camara.x
    return camara.y - 120 if centro else camara.y

